/* XLSX-Lite local parser for Chrome extension prototype. Supports HTML-table XLS, CSV/TSV text, and .xlsx via JSZip. Not a BIFF8 .xls parser. */
(function(){
  function clean(s){return String(s==null?'':s).replace(/\s+/g,' ').trim();}
  function xmlText(node){return node?clean(node.textContent):'';}
  function parseXml(text){return new DOMParser().parseFromString(text,'application/xml');}
  function colIndex(ref){var m=String(ref||'').match(/[A-Z]+/i); if(!m) return -1; var s=m[0].toUpperCase(), n=0; for(var i=0;i<s.length;i++) n=n*26+(s.charCodeAt(i)-64); return n-1;}
  function rowsToSheet(rows){return {__rows: rows};}
  function htmlToRows(text){
    var doc=new DOMParser().parseFromString(text,'text/html');
    var table=doc.querySelector('table');
    if(table) return Array.from(table.querySelectorAll('tr')).map(function(tr){return Array.from(tr.querySelectorAll('th,td')).map(function(td){return clean(td.textContent);});});
    return String(text).split(/\r?\n/).filter(function(x){return clean(x);}).map(function(line){return line.split(/\t|,/).map(clean);});
  }
  function textWorkbook(text){return {SheetNames:['Sheet1'], Sheets:{Sheet1: rowsToSheet(htmlToRows(text))}};}
  function relTarget(base, target){
    if(!target) return '';
    if(target[0]=='/') return target.replace(/^\//,'');
    var stack=base.split('/'); stack.pop();
    target.split('/').forEach(function(p){ if(!p||p=='.') return; if(p=='..') stack.pop(); else stack.push(p); });
    return stack.join('/');
  }
  async function parseXlsxZip(arrayBuffer){
    if(!window.JSZip) throw new Error('JSZip library is missing.');
    var zip=await JSZip.loadAsync(arrayBuffer);
    async function read(path){var f=zip.file(path); return f?await f.async('text'):'';}
    var wbXml=await read('xl/workbook.xml');
    if(!wbXml) throw new Error('Invalid .xlsx: xl/workbook.xml not found');
    var wb=parseXml(wbXml);
    var relXml=await read('xl/_rels/workbook.xml.rels');
    var rels={};
    if(relXml){
      var relDoc=parseXml(relXml);
      Array.from(relDoc.getElementsByTagName('Relationship')).forEach(function(r){rels[r.getAttribute('Id')]=relTarget('xl/workbook.xml', r.getAttribute('Target'));});
    }
    var shared=[];
    var ssXml=await read('xl/sharedStrings.xml');
    if(ssXml){
      var ss=parseXml(ssXml);
      Array.from(ss.getElementsByTagName('si')).forEach(function(si){shared.push(clean(Array.from(si.getElementsByTagName('t')).map(function(t){return t.textContent||'';}).join('')));});
    }
    var sheetNames=[], Sheets={};
    var sheetNodes=Array.from(wb.getElementsByTagName('sheet'));
    for(var si=0; si<sheetNodes.length; si++){
      var sn=sheetNodes[si];
      var name=sn.getAttribute('name')||('Sheet'+(si+1));
      var rid=sn.getAttribute('r:id')||sn.getAttribute('id');
      var path=rels[rid] || ('xl/worksheets/sheet'+(si+1)+'.xml');
      var sx=await read(path);
      var rows=[];
      if(sx){
        var sd=parseXml(sx);
        Array.from(sd.getElementsByTagName('row')).forEach(function(rowNode){
          var row=[];
          Array.from(rowNode.getElementsByTagName('c')).forEach(function(c){
            var idx=colIndex(c.getAttribute('r'));
            if(idx<0) idx=row.length;
            var t=c.getAttribute('t');
            var val='';
            if(t==='inlineStr') val=xmlText(c.getElementsByTagName('t')[0]);
            else { val=xmlText(c.getElementsByTagName('v')[0]); if(t==='s') val=shared[Number(val)]||''; }
            row[idx]=val;
          });
          while(row.length && row[row.length-1]===undefined) row.pop();
          rows.push(row.map(function(x){return x==null?'':x;}));
        });
      }
      sheetNames.push(name); Sheets[name]=rowsToSheet(rows);
    }
    return {SheetNames:sheetNames, Sheets:Sheets};
  }
  async function readAsync(data, opts){
    var ab=data instanceof ArrayBuffer?data:(data&&data.buffer?data.buffer:data);
    var probe=new Uint8Array(ab.slice(0,4));
    if(probe[0]===0x50 && probe[1]===0x4b) return await parseXlsxZip(ab);
    var text=new TextDecoder('utf-8',{fatal:false}).decode(ab);
    return textWorkbook(text);
  }
  function read(data, opts){
    var ab=data instanceof ArrayBuffer?data:(data&&data.buffer?data.buffer:data);
    var probe=new Uint8Array(ab.slice(0,4));
    if(probe[0]===0x50 && probe[1]===0x4b) throw new Error('This local XLSX parser uses async readAsync() for .xlsx zip files.');
    var text=new TextDecoder('utf-8',{fatal:false}).decode(ab);
    return textWorkbook(text);
  }
  window.XLSX={
    read:read,
    readAsync:readAsync,
    utils:{ sheet_to_json:function(ws, opts){return (ws&&ws.__rows)||[];} },
    version:'xlsx-lite-local-0.1.4'
  };
})();
